window.kbPageData["views/entry/k-60e2ec1fe07704d6"] = {"key":"entry/k-60e2ec1fe07704d6","state":{"route":"entry/k-60e2ec1fe07704d6"},"node":{"id":"k-60e2ec1fe07704d6","mode":"k","title":"面临问题","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["事实与事件"],"出处性质":["公报解读正文"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["二十届五中全会"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"党的二十届五中全会","slug":"6a94c2ad76dd"}],"directorySummary":"二、面临问题\n全会强调，全面从严治党具备许多有利条件，同时面临许多新情况新问题。随着世情国\n情党情发生深刻变化，党团结带领人民维护国家主权、安全、发展利益任务更加艰巨，党团\n结带领人民推动改革发展、维护社会和谐稳定任务更加艰巨，党保持先进性和纯洁性任务更\n加艰巨。这些对党在新形势下的执政能力、领导水…","sources":[{"id":"ff13708461214eb0","label":"面临问题","topic":"二十届五中全会","category":"时政","text":"二、面临问题\n全会强调，全面从严治党具备许多有利条件，同时面临许多新情况新问题。随着世情国\n情党情发生深刻变化，党团结带领人民维护国家主权、安全、发展利益任务更加艰巨，党团\n结带领人民推动改革发展、维护社会和谐稳定任务更加艰巨，党保持先进性和纯洁性任务更\n加艰巨。这些对党在新形势下的执政能力、领导水平、队伍素质、拒腐防变带来重大挑战，\n党面临的“四大考验”①和“四种危险”②是长期的、复杂的、严峻的。全党必须从巩固党的\n长期执政地位、实现中华民族伟大复兴的战略高度，深刻认识持之以恒推进全面从严治党的\n重大意义，坚定信心，保持定力，以更高标准、更实举措把新时代全面从严治党宝贵经验③\n坚持好、运用好，把党的建设面临的突出问题④整治好、解决好，把管党治党形成的良好政\n治局面巩固好、发展好。","source":{"doc":"41195a191a57c1c36332","first":8,"last":9,"page":8,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-60e2ec1fe07704d6":[]}};
